from django.db import migrations


def move_vest_ids_to_smart_vests(apps, schema_editor):
    """Make SmartVest.worker the only worker-vest link.

    For each worker's old vest_id string: attach the matching SmartVest if it
    is unassigned, or create a SmartVest when none exists. A vest already
    assigned to a *different* worker keeps that assignment (the FK wins) and
    the conflicting string is dropped; it is printed so it can be reviewed.
    """
    Worker = apps.get_model("workers", "Worker")
    SmartVest = apps.get_model("workers", "SmartVest")
    for worker in Worker.objects.exclude(vest_id=""):
        if SmartVest.objects.filter(worker=worker).exists():
            continue
        vest = SmartVest.objects.filter(vest_id=worker.vest_id).first()
        if vest is None:
            SmartVest.objects.create(vest_id=worker.vest_id, worker=worker)
        elif vest.worker_id is None:
            vest.worker = worker
            vest.save(update_fields=["worker"])
        else:
            print(
                f"\n  worker {worker.pk} ({worker.name}) listed vest {worker.vest_id}, "
                f"which is assigned to worker {vest.worker_id}; left unassigned"
            )


def restore_vest_ids(apps, schema_editor):
    Worker = apps.get_model("workers", "Worker")
    SmartVest = apps.get_model("workers", "SmartVest")
    for worker in Worker.objects.all():
        vest = SmartVest.objects.filter(worker=worker).first()
        worker.vest_id = vest.vest_id if vest else f"UNASSIGNED-{worker.pk}"
        worker.save(update_fields=["vest_id"])


